import React, { useEffect, useState } from "react";
import { Outlet, Link, useNavigate, useLocation } from "react-router-dom";
import {
  FaBookOpen,
  FaChalkboardTeacher,
  FaUserGraduate,
  FaCalendarAlt,
  FaSignOutAlt,
  FaGraduationCap,
  FaTasks,
  FaClipboardList,
  FaBrain,
  FaFolderOpen,
  FaClock,
  FaBell,
  FaChartLine,
  FaBars
} from "react-icons/fa";
import "./theme.css";

function MainLayout() {
  const navigate = useNavigate();
  const location = useLocation();
  const [isMobile, setIsMobile] = useState(window.innerWidth < 900);
  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const [theme, setTheme] = useState(localStorage.getItem("theme") || "light");
  const [sidebarOpen, setSidebarOpen] = useState(true);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 900;
      setIsMobile(mobile);

      if (mobile) {
        setSidebarOpen(false);
    } else {
      setSidebarOpen(true);
    }
  };

  window.addEventListener("resize", handleResize);
  handleResize();

  return () => window.removeEventListener("resize", handleResize);
}, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  const linkStyle = (path) => {
    const active = location.pathname === path;
    return {
      display: "flex",
      alignItems: "center",
      gap: "12px",
      padding: "12px 14px",
      borderRadius: "14px",
      color: active ? "#ffffff" : "var(--text)",
      background: active ? "linear-gradient(135deg, var(--primary), #a78bfa)" : "transparent",
      fontWeight: 700,
      marginBottom: "8px",
      transition: "0.2s ease"
    };
  };

  return (
    <div
      style={{
        display: "flex",
        minHeight: "100vh",
        background: "var(--bg)"
      }}
    >
      <aside
        style={{
          width: sidebarOpen ? "280px" : "86px",
          background: "var(--surface)",
          borderRight: "1px solid var(--border)",
          padding: "18px 14px",
          transition: "0.25s ease",
          position: "sticky",
          top: 0,
          height: "100vh",
          overflowY: "auto",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          boxShadow: "var(--shadow-sm)"
        }}
      >
        <div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: sidebarOpen ? "space-between" : "center",
              marginBottom: "18px"
            }}
          >
            {sidebarOpen ? (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "10px",
                  color: "var(--primary)",
                  fontSize: "22px",
                  fontWeight: 800
                }}
              >
                <FaGraduationCap />
                <span>LMS Pro</span>
              </div>
            ) : (
              <div style={{ color: "var(--primary)", fontSize: "22px" }}>
                <FaGraduationCap />
              </div>
            )}

            <button
              className="btn btn-secondary"
              style={{ padding: "10px 12px" }}
              onClick={() => setSidebarOpen(!sidebarOpen)}
            >
              <FaBars />
            </button>
          </div>

          {sidebarOpen && (
            <button
              className="btn btn-primary"
              style={{ width: "100%", marginBottom: "18px" }}
              onClick={() => setTheme(theme === "light" ? "dark" : "light")}
            >
              {theme === "light" ? "🌙 Dark Mode" : "☀ Light Mode"}
            </button>
          )}

          {sidebarOpen && (
            <div
              style={{
                fontSize: "12px",
                color: "var(--muted)",
                textTransform: "uppercase",
                letterSpacing: "0.8px",
                margin: "10px 8px"
              }}
            >
              Dashboard
            </div>
          )}

          {role === "teacher" && (
            <Link to="/teacher-dashboard" style={linkStyle("/teacher-dashboard")}>
              <FaChalkboardTeacher />
              {sidebarOpen && <span>Teacher Dashboard</span>}
            </Link>
          )}

          {role === "student" && (
            <Link to="/student-dashboard" style={linkStyle("/student-dashboard")}>
              <FaUserGraduate />
              {sidebarOpen && <span>Student Dashboard</span>}
            </Link>
          )}

          {sidebarOpen && (
            <div
              style={{
                fontSize: "12px",
                color: "var(--muted)",
                textTransform: "uppercase",
                letterSpacing: "0.8px",
                margin: "18px 8px 10px"
              }}
            >
              Learning
            </div>
          )}

          <Link to="/courses" style={linkStyle("/courses")}>
            <FaBookOpen />
            {sidebarOpen && <span>Courses</span>}
          </Link>

          {role === "student" && (
            <>
              <Link to="/planner" style={linkStyle("/planner")}>
                <FaCalendarAlt />
                {sidebarOpen && <span>Planner</span>}
              </Link>

              <Link to="/smart-planner" style={linkStyle("/smart-planner")}>
                <FaBrain />
                {sidebarOpen && <span>Smart Planner</span>}
              </Link>

              <Link to="/study-tracker" style={linkStyle("/study-tracker")}>
                <FaClock />
                {sidebarOpen && <span>Study Tracker</span>}
              </Link>

              <Link to="/reminders" style={linkStyle("/reminders")}>
                <FaBell />
                {sidebarOpen && <span>Reminders</span>}
              </Link>

              <Link to="/student-assignments" style={linkStyle("/student-assignments")}>
                <FaClipboardList />
                {sidebarOpen && <span>Assignments</span>}
              </Link>

              <Link to="/student-quiz" style={linkStyle("/student-quiz")}>
                <FaTasks />
                {sidebarOpen && <span>Quiz</span>}
              </Link>

              <Link to="/materials" style={linkStyle("/materials")}>
                <FaFolderOpen />
                {sidebarOpen && <span>Materials</span>}
              </Link>

              <Link to="/pomodoro" style={linkStyle("/pomodoro")}>
                <FaClock />
                {sidebarOpen && <span>Pomodoro</span>}
              </Link>
            </>
          )}

          {role === "teacher" && (
            <>
              <Link to="/teacher-assignments" style={linkStyle("/teacher-assignments")}>
                <FaClipboardList />
                {sidebarOpen && <span>Assignments</span>}
              </Link>

              <Link to="/teacher-quiz" style={linkStyle("/teacher-quiz")}>
                <FaTasks />
                {sidebarOpen && <span>Quiz</span>}
              </Link>

              <Link to="/quiz-analytics" style={linkStyle("/quiz-analytics")}>
                <FaChartLine />
                {sidebarOpen && <span>Quiz Analytics</span>}
              </Link>

              <Link to="/upload-material" style={linkStyle("/upload-material")}>
                <FaFolderOpen />
                {sidebarOpen && <span>Upload Notes</span>}
              </Link>
            </>
          )}
        </div>

        <div style={{ marginTop: "20px" }}>
          {sidebarOpen ? (
            <button
              className="btn btn-danger"
              style={{ width: "100%" }}
              onClick={handleLogout}
            >
              <FaSignOutAlt style={{ marginRight: "8px" }} />
              Logout
            </button>
          ) : (
            <button
              className="btn btn-danger"
              style={{ width: "100%" }}
              onClick={handleLogout}
            >
              <FaSignOutAlt />
            </button>
          )}
        </div>
      </aside>

      <main style={{ flex: 1, minWidth: 0 }}>
        <div style={{ padding: "16px 20px 0" }}>
          <div
            style={{
              background: "var(--surface)",
              border: "1px solid var(--border)",
              boxShadow: "var(--shadow-sm)",
              borderRadius: "18px",
              padding: "14px 18px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              gap: "12px",
              marginBottom: "16px"
            }}
          >
            <div>
              <div style={{ fontWeight: 800, color: "var(--text)" }}>
                Hello, {userName || "User"}
              </div>
              <div style={{ fontSize: "13px", color: "var(--muted)" }}>
                {role === "teacher"
                  ? "Manage learning content professionally."
                  : "Stay consistent and improve every day."}
              </div>
            </div>

            {!sidebarOpen && (
              <button
                className="btn btn-primary"
                onClick={() => setTheme(theme === "light" ? "dark" : "light")}
              >
                {theme === "light" ? "🌙" : "☀"}
              </button>
            )}
          </div>
        </div>

        <Outlet />
      </main>
    </div>
  );
}

export default MainLayout;
